"""Systems Mastery S01: how a computer runs programs."""
import sysviz as v

STACK_VIZ = v.figure(
    720, 296,
    [v.box(210, 6, 300, 46, "your program", "acc", "python, ls, nginx"),
     v.arrow(360, 52, 360, 82),
     v.box(210, 82, 300, 46, "C library (libc)", "", "open(), read(), printf()"),
     v.arrow(360, 128, 360, 172, "system call"),
     v.box(210, 172, 300, 46, "the kernel", "ink", "checks permissions, does the work"),
     v.arrow(360, 218, 360, 242),
     v.box(210, 242, 300, 46, "hardware", "", "CPU, RAM, disk, network card"),
     v.text(100, 34, "user mode", "dg-s"), v.text(100, 200, "kernel mode", "dg-s"),
     v.text(620, 34, "can compute only", "dg-s"), v.text(620, 200, "can do anything", "dg-s")],
    "User mode and kernel mode", "Programs ask; only the kernel touches the hardware")

